local Player = game:GetService("Players").LocalPlayer
if not Player then
    error("Player not found")
end

local PlayerGui = Player:WaitForChild("PlayerGui")
local _styles = {
    Middle = require(script.styles.Middle),
    Bottom = require(script.styles.Bottom),
    Top = require(script.styles.Top)
}
local module = {}
local _gui = nil

function module.new(context)
    local self = {}
    setmetatable(self, module)
    return self
end

local function getTextInstance(text)
    local textLabel = Instance.new("TextLabel")
    textLabel.BackgroundTransparency = 1
    textLabel.Size = UDim2.new(1, 0, 1, 0)
    textLabel.Position = UDim2.new(.5, .5)
    textLabel.AnchorPoint = Vector2.new(.5, .5)
    textLabel.TextColor3 = Color3.fromRGB(255, 140, 0)
    textLabel.TextStrokeColor3 = Color3.fromRGB(70, 70, 70)
    textLabel.TextStrokeTransparency = 0
    textLabel.Text = text
    textLabel.TextScaled = true
    textLabel.TextWrapped = true
    textLabel.TextXAlignment = Enum.TextXAlignment.Center
    textLabel.TextYAlignment = Enum.TextYAlignment.Center
    textLabel.Font = Enum.Font.ArialBold
    textLabel.FontFace.Weight = Enum.FontWeight.Bold
    textLabel.RichText = true
    return textLabel
end

local function createGui()
    _gui = Instance.new("ScreenGui")
    _gui.Name = "NezaToastGui"
    _gui.DisplayOrder = 10^6
    _gui.ResetOnSpawn = false
    _gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    _gui.IgnoreGuiInset = false
    _gui.Parent = PlayerGui

    local top = Instance.new("Frame", _gui)
    top.Name = "Top"
    top.Size = UDim2.new(1, 0, .22, 0)
    top.BackgroundTransparency = 1
    top.Position = UDim2.new(.5, 0, .05, 0)
    top.AnchorPoint = Vector2.new(.5, 0)
    local uilistlayout = Instance.new("UIListLayout", top)
    uilistlayout.FillDirection = Enum.FillDirection.Vertical
    uilistlayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    uilistlayout.VerticalAlignment = Enum.VerticalAlignment.Top
    uilistlayout.Padding = UDim.new(0.025, 0)
    _styles.Top:SetContent(top)

    local bottom = Instance.new("Frame", _gui)
    bottom.Name = "Bottom"
    bottom.Size = UDim2.new(1, 0, .22, 0)
    bottom.BackgroundTransparency = 1
    bottom.Position = UDim2.new(.5, 0, .95, 0)
    bottom.AnchorPoint = Vector2.new(.5, 1)
    local uilistlayout = Instance.new("UIListLayout", bottom)
    uilistlayout.FillDirection = Enum.FillDirection.Vertical
    uilistlayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    uilistlayout.VerticalAlignment = Enum.VerticalAlignment.Bottom
    uilistlayout.Padding = UDim.new(0.025, 0)
    _styles.Bottom:SetContent(bottom)
    
    return _gui
end

local function getGui()
    if not _gui then
        _gui = createGui()
    end
    return _gui
end

local function getToastItem(context)
    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(1, 0, .18, 0)
    frame.Position = UDim2.new(.5, 0, .5, 0)
    frame.AnchorPoint = Vector2.new(.5, .5)
    frame.BackgroundTransparency = 1

    local uilistlayout = Instance.new("UIListLayout", frame)
    uilistlayout.FillDirection = Enum.FillDirection.Vertical
    uilistlayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    uilistlayout.VerticalAlignment = Enum.VerticalAlignment.Center

    context.Parent = frame

    return frame
end

function module:ShowTop(context)
    self:Show(context, "Top")
end

function module:ShowBottom(context)
    self:Show(context, "Bottom")
end

function module:Show(context, where: string?)
    where = where or "Bottom"
    if _styles[where] then
        getGui()
        if typeof(context) == "string" then
            context = getTextInstance(context)
        elseif typeof(context) == "Instance" then
            
        end
        _styles[where]:Add(getToastItem(context))
    end
end

return module